/bin/zsh -lc "python3 -B - <<'PY'
from copy import deepcopy
from ledger import Ledger

for label, balances in ((\"negative initial balance\", {\"a\": -1}), (\"boolean initial balance\", {\"a\": True})):
    try:
        Ledger(balances)
    except Exception as error:
        outcome = type(error).__name__
    else:
        outcome = \"accepted\"
    print(f\"{label}: expected ValueError; observed {outcome}\")

cases = [
    (\"unavailable target\", lambda ledger: ledger.transfer(\"a\", \"missing\", 1, \"bad\")),
    (\"negative amount\", lambda ledger: ledger.transfer(\"a\", \"b\", -1, \"bad\")),
    (\"empty key\", lambda ledger: ledger.transfer(\"a\", \"b\", 1, \"\")),
    (\"malformed batch operation\", lambda ledger: ledger.batch([
        dict(source=\"a\", target=\"b\", amount=1, key=\"early\"),
        dict(source=\"a\", target=\"b\", amount=1),
    ])),
    (\"non-list batch\", lambda ledger: ledger.batch(())),
]
for label, action in cases:
    ledger = Ledger({\"a\": 10, \"b\": 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        action(ledger)
    except Exception as error:
        outcome = type(error).__name__
    else:
        outcome = \"accepted\"
    unchanged = (ledger.balances, ledger.history) == before
    print(f\"{label}: expected ValueError and unchanged state; observed {outcome}, unchanged={unchanged}\")
PY"

